import React, { useState, useRef, useEffect, useCallback } from 'react';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';
import ProfModal from './ProfModal';

/* ════════════════════════════════════════════════
   COMPOSANTS UTILITAIRES
════════════════════════════════════════════════ */

function Stars({ n, size = 13 }) {
  const v = parseFloat(n) || 0;
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 2 }}>
      {[1,2,3,4,5].map(i => (
        <span key={i} style={{ color: i <= Math.round(v) ? '#f59e0b' : 'var(--border)', fontSize: size }}>★</span>
      ))}
      <span style={{ fontSize: '.72rem', color: 'var(--text2)', marginLeft: 3 }}>{v.toFixed(1)}</span>
    </span>
  );
}

function ScoreBar({ score }) {
  const color = score >= 80 ? '#43e97b' : score >= 65 ? '#6c63ff' : score >= 50 ? '#f59e0b' : '#ff6584';
  const label = score >= 80 ? 'Excellent' : score >= 65 ? 'Très bon' : score >= 50 ? 'Bon' : 'Possible';
  return (
    <div style={{ marginBottom: 8 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
        <span style={{ fontSize: '.72rem', color: 'var(--text2)', fontWeight: 600 }}>Score de matching</span>
        <span style={{ fontSize: '.78rem', fontWeight: 800, color }}>
          {score}/100 — {label}
        </span>
      </div>
      <div style={{ height: 6, background: 'var(--border)', borderRadius: 3, overflow: 'hidden' }}>
        <div style={{ height: '100%', width: `${score}%`, background: `linear-gradient(90deg,${color},${color}bb)`, borderRadius: 3, transition: 'width .8s ease' }} />
      </div>
      {/* Détail score */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 4, marginTop: 6 }}>
        {[
          ['📚', 'Matière',   score >= 80 ? 30 : Math.round(score * 0.3), 30],
          ['🎓', 'Niveau',    Math.round(score * 0.2), 20],
          ['📡', 'Mode',      Math.round(score * 0.15), 15],
          ['💰', 'Budget',    Math.round(score * 0.15), 15],
          ['📅', 'Dispo',     score >= 50 ? 10 : 5, 10],
          ['⭐', 'Réputation', Math.round(score * 0.1), 10],
        ].map(([icon, label, val, max]) => (
          <div key={label} style={{ fontSize: '.62rem', color: 'var(--text2)', textAlign: 'center' }}>
            {icon} {label} {val}/{max}
          </div>
        ))}
      </div>
    </div>
  );
}

/* ── Carte professeur dans le chat ── */
function ProfChatCard({ prof, onViewProfile, onReserve, rank }) {
  const [hovered, setHovered] = useState(false);
  const nom    = prof.nom || `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim();
  const score  = prof.score?.total || 0;
  const medals = ['🥇', '🥈', '🥉'];

  const tarifMin = Math.min(
    ...[prof.tarif_en_ligne, prof.tarif_presentiel]
      .filter(v => v && parseFloat(v) > 0)
      .map(Number)
  );

  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        background: 'var(--card)',
        border: hovered ? '1px solid rgba(108,99,255,0.5)' : '1px solid var(--border)',
        borderRadius: 18,
        padding: 18,
        transition: 'all .25s',
        boxShadow: hovered ? '0 12px 32px rgba(108,99,255,0.15)' : 'none',
        transform: hovered ? 'translateY(-3px)' : 'none',
      }}
    >
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 }}>
        <div style={{ fontSize: '1.4rem', flexShrink: 0 }}>{medals[rank - 1] || `#${rank}`}</div>
        <div style={{ width: 46, height: 46, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem', overflow: 'hidden', flexShrink: 0 }}>
          {prof.photo_url
            ? <img src={`http://localhost:8001${prof.photo_url}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            : '👨‍🏫'}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '.95rem', marginBottom: 2 }}>{nom}</div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
            <Stars n={prof.note_moyenne} />
            {prof.ville && <span style={{ fontSize: '.7rem', color: 'var(--text2)' }}>📍 {prof.ville}</span>}
          </div>
        </div>
        {tarifMin && isFinite(tarifMin) && (
          <div style={{ textAlign: 'right', flexShrink: 0 }}>
            <div style={{ fontSize: '.68rem', color: 'var(--text2)' }}>dès</div>
            <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem', color: '#43e97b' }}>{tarifMin} DT/h</div>
          </div>
        )}
      </div>

      {/* Score matching */}
      <ScoreBar score={score} />

      {/* Matières */}
      {prof.matieres && prof.matieres.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, marginBottom: 10 }}>
          {prof.matieres.map(m => (
            <span key={m} style={{ fontSize: '.67rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20, background: 'rgba(108,99,255,0.08)', color: '#6c63ff', border: '1px solid rgba(108,99,255,0.15)' }}>
              {m}
            </span>
          ))}
        </div>
      )}

      {/* Prochaine dispo */}
      {prof.disponibilites && prof.disponibilites.length > 0 && (
        <div style={{ fontSize: '.73rem', color: 'var(--text2)', marginBottom: 12, padding: '6px 10px', background: 'rgba(67,233,123,0.07)', borderRadius: 8, border: '1px solid rgba(67,233,123,0.15)' }}>
          📅 Prochain créneau : {prof.disponibilites[0].date} · {prof.disponibilites[0].heure_debut} → {prof.disponibilites[0].heure_fin}
          <span style={{ marginLeft: 6, color: prof.disponibilites[0].mode === 'en_ligne' ? '#38bdf8' : '#43e97b' }}>
            {prof.disponibilites[0].mode === 'en_ligne' ? '🌐' : '🏫'}
          </span>
        </div>
      )}

      {/* Bio courte */}
      {prof.bio && (
        <p style={{ fontSize: '.78rem', color: 'var(--text2)', lineHeight: 1.5, margin: '0 0 12px', overflow: 'hidden', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical' }}>
          {prof.bio}
        </p>
      )}

      {/* Actions */}
      <div style={{ display: 'flex', gap: 8 }}>
        <button
          onClick={() => onViewProfile(prof)}
          style={{ flex: 1, padding: '9px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, cursor: 'pointer', fontWeight: 600, fontSize: '.8rem', color: 'var(--text)', transition: 'all .15s' }}
          onMouseEnter={e => { e.currentTarget.style.borderColor='#6c63ff'; e.currentTarget.style.color='#6c63ff'; }}
          onMouseLeave={e => { e.currentTarget.style.borderColor='var(--border)'; e.currentTarget.style.color='var(--text)'; }}
        >
          👤 Voir profil
        </button>
        <button
          onClick={() => onReserve(prof)}
          style={{ flex: 2, padding: '9px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 10, cursor: 'pointer', fontWeight: 700, fontSize: '.8rem', color: '#fff', transition: 'all .2s', boxShadow: '0 3px 10px rgba(108,99,255,0.3)' }}
        >
          📅 Réserver un cours
        </button>
      </div>
    </div>
  );
}

/* ── Bulle message ── */
function MessageBubble({ msg }) {
  const isUser = msg.role === 'user';
  return (
    <div style={{ display: 'flex', justifyContent: isUser ? 'flex-end' : 'flex-start', marginBottom: 16, gap: 10, alignItems: 'flex-end' }}>
      {!isUser && (
        <div style={{ width: 34, height: 34, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.9rem', flexShrink: 0 }}>
          🤖
        </div>
      )}
      <div style={{ maxWidth: '78%' }}>
        <div style={{
          padding: '12px 16px',
          borderRadius: isUser ? '18px 18px 4px 18px' : '18px 18px 18px 4px',
          background: isUser ? 'linear-gradient(135deg,#6c63ff,#8b5cf6)' : 'var(--surface2)',
          color: isUser ? '#fff' : 'var(--text)',
          fontSize: '.88rem',
          lineHeight: 1.65,
          border: isUser ? 'none' : '1px solid var(--border)',
          whiteSpace: 'pre-wrap',
        }}>
          {msg.content}
        </div>
        <div style={{ fontSize: '.65rem', color: 'var(--text2)', marginTop: 4, textAlign: isUser ? 'right' : 'left' }}>
          {msg.time}
        </div>
      </div>
      {isUser && (
        <div style={{ width: 34, height: 34, borderRadius: '50%', background: 'linear-gradient(135deg,#ff6584,#f43f5e)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.9rem', flexShrink: 0 }}>
          👨‍🎓
        </div>
      )}
    </div>
  );
}

/* ── Typing indicator ── */
function TypingIndicator() {
  return (
    <div style={{ display: 'flex', alignItems: 'flex-end', gap: 10, marginBottom: 16 }}>
      <div style={{ width: 34, height: 34, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.9rem', flexShrink: 0 }}>
        🤖
      </div>
      <div style={{ padding: '12px 18px', background: 'var(--surface2)', borderRadius: '18px 18px 18px 4px', border: '1px solid var(--border)', display: 'flex', gap: 5, alignItems: 'center' }}>
        <style>{`@keyframes bounce{0%,80%,100%{transform:translateY(0)}40%{transform:translateY(-6px)}} .dot{width:7px;height:7px;borderRadius:50%;background:#6c63ff;animation:bounce 1.4s infinite;}`}</style>
        <div className="dot" style={{ animationDelay: '0s' }} />
        <div className="dot" style={{ animationDelay: '.2s' }} />
        <div className="dot" style={{ animationDelay: '.4s' }} />
      </div>
    </div>
  );
}

