const SUGGESTIONS = [
  "Je cherche un prof de maths pour le bac",
  "Prof de physique en ligne à Tunis",
  "Cours d'anglais pas cher pour collège",
  "Professeur de programmation Python",
  "Cours de français pour lycée",
  "Prof d'arabe pour niveau primaire",
];

/* ════════════════════════════════════════════════
   PAGE CHATBOT PRINCIPALE
════════════════════════════════════════════════ */
export default function Chatbot() {
  const { user } = useAuth();
  const [messages, setMessages]     = useState([]);
  const [input, setInput]           = useState('');
  const [loading, setLoading]       = useState(false);
  const [top3Profs, setTop3Profs]   = useState([]);
  const [selectedProf, setSelectedProf] = useState(null);
  const [showWelcome, setShowWelcome]   = useState(true);
  const bottomRef  = useRef(null);
  const inputRef   = useRef(null);

  // Scroll automatique
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, loading, top3Profs]);

  // Focus input
  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  const getTime = () => new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

  const sendMessage = useCallback(async (text) => {
    const userText = (text || input).trim();
    if (!userText || loading) return;

    setInput('');
    setShowWelcome(false);

    const userMsg = { role: 'user', content: userText, time: getTime() };
    setMessages(prev => [...prev, userMsg]);
    setLoading(true);
    setTop3Profs([]);

    // Construire l'historique pour l'API (sans les champs time)
    const history = [...messages, userMsg].map(m => ({
      role:    m.role,
      content: m.content,
    }));

    try {
      const res = await api.post('/api/chatbot/chat', { messages: history });
      const { reply, top3_profs } = res.data;

      setMessages(prev => [
        ...prev,
        { role: 'assistant', content: reply, time: getTime() },
      ]);

      if (top3_profs && top3_profs.length > 0) {
        setTop3Profs(top3_profs);
      }
    } catch (e) {
      const status  = e?.response?.status;
      const detail  = e?.response?.data?.detail;
      let errMsg = '❌ Une erreur est survenue. Réessayez dans quelques instants.';
      if (status === 503 || (detail && detail.includes('chargement'))) {
        errMsg = '⏳ Le modèle IA démarre (30s environ). Réessayez dans quelques secondes.';
      } else if (status === 429) {
        errMsg = '⚠️ Limite de requêtes atteinte. Attendez quelques secondes.';
      } else if (status === 504) {
        errMsg = '⏱️ Délai dépassé. Le modèle est surchargé, réessayez.';
      } else if (status === 401) {
        errMsg = '🔑 Clé HuggingFace invalide. Contactez ladministrateur.';
      } else if (detail) {
        errMsg = `❌ ${detail}`;
      }
      setMessages(prev => [
        ...prev,
        { role: 'assistant', content: errMsg, time: getTime() },
      ]);
    } finally {
      setLoading(false);
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [input, messages, loading]);

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  const handleViewProfile = async (prof) => {
    try {
      const res = await api.get(`/api/chatbot/prof-detail/${prof.id}`);
      setSelectedProf(res.data);
    } catch {
      setSelectedProf(prof);
    }
  };

  const handleReserve = (prof) => {
    // Ouvrir le modal avec l'onglet disponibilités
    handleViewProfile(prof);
  };

  const resetChat = () => {
    setMessages([]);
    setTop3Profs([]);
    setShowWelcome(true);
    setInput('');
  };

  return (
    <div style={{ display: 'flex', height: 'calc(100vh - 64px)', overflow: 'hidden', background: 'var(--bg)' }}>

      {/* ════ COLONNE GAUCHE — Chat ════ */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', borderRight: '1px solid var(--border)', minWidth: 0 }}>

        {/* Header chat */}
        <div style={{ padding: '20px 28px', borderBottom: '1px solid var(--border)', background: 'var(--surface)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
            <div style={{ width: 44, height: 44, borderRadius: 13, background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.3rem', boxShadow: '0 4px 14px rgba(108,99,255,0.3)' }}>
              🤖
            </div>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem' }}>EduBot — Assistant IA</div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: '.75rem', color: 'var(--text2)' }}>
                <span style={{ width: 7, height: 7, borderRadius: '50%', background: '#43e97b', display: 'inline-block' }} />
                En ligne · Powered by Claude AI
              </div>
            </div>
          </div>
          <button
            onClick={resetChat}
            style={{ padding: '7px 14px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, cursor: 'pointer', fontSize: '.78rem', color: 'var(--text2)', fontWeight: 600, display: 'flex', alignItems: 'center', gap: 5 }}
          >
            🔄 Nouvelle conversation
          </button>
        </div>

        {/* Zone messages */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '24px 28px' }}>

          {/* Écran de bienvenue */}
          {showWelcome && (
            <div style={{ textAlign: 'center', padding: '40px 20px 20px' }}>
              <div style={{ fontSize: '3rem', marginBottom: 16 }}>🎓</div>
              <h2 style={{ fontFamily: 'Syne', fontSize: '1.4rem', fontWeight: 800, margin: '0 0 10px' }}>
                Bonjour {user?.prenom || ''} !
              </h2>
              <p style={{ color: 'var(--text2)', fontSize: '.9rem', lineHeight: 1.7, maxWidth: 480, margin: '0 auto 32px' }}>
                Je suis EduBot, votre assistant intelligent. Décrivez-moi vos besoins et je vous recommande les 3 professeurs les plus adaptés avec un score de matching personnalisé.
              </p>

              {/* Suggestions rapides */}
              <div style={{ marginBottom: 20 }}>
                <div style={{ fontSize: '.75rem', fontWeight: 700, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.08em', marginBottom: 12 }}>
                  💡 Questions fréquentes
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, justifyContent: 'center' }}>
                  {SUGGESTIONS.map(s => (
                    <button
                      key={s}
                      onClick={() => sendMessage(s)}
                      style={{ padding: '8px 16px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 20, cursor: 'pointer', fontSize: '.8rem', color: 'var(--text)', fontWeight: 500, transition: 'all .15s' }}
                      onMouseEnter={e => { e.currentTarget.style.borderColor='#6c63ff'; e.currentTarget.style.color='#6c63ff'; e.currentTarget.style.background='rgba(108,99,255,0.06)'; }}
                      onMouseLeave={e => { e.currentTarget.style.borderColor='var(--border)'; e.currentTarget.style.color='var(--text)'; e.currentTarget.style.background='var(--surface2)'; }}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              {/* Fonctionnalités */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 12, maxWidth: 560, margin: '0 auto' }}>
                {[
                  { icon: '🎯', title: 'Matching intelligent', desc: 'Score personnalisé selon vos critères' },
                  { icon: '📊', title: 'Comparaison', desc: 'Top 3 avec détail des scores' },
                  { icon: '📅', title: 'Réservation directe', desc: 'Réservez sans quitter le chat' },
                ].map(f => (
                  <div key={f.title} style={{ padding: 14, background: 'var(--surface2)', borderRadius: 14, border: '1px solid var(--border)', textAlign: 'center' }}>
                    <div style={{ fontSize: '1.4rem', marginBottom: 6 }}>{f.icon}</div>
                    <div style={{ fontWeight: 700, fontSize: '.8rem', marginBottom: 4 }}>{f.title}</div>
                    <div style={{ fontSize: '.72rem', color: 'var(--text2)' }}>{f.desc}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Messages */}
          {messages.map((msg, i) => (
            <MessageBubble key={i} msg={msg} />
          ))}

          {/* Loading */}
          {loading && <TypingIndicator />}

          <div ref={bottomRef} />
        </div>

        {/* Zone de saisie */}
        <div style={{ padding: '16px 28px', background: 'var(--surface)', borderTop: '1px solid var(--border)' }}>
          <div style={{ display: 'flex', gap: 12, alignItems: 'flex-end', background: 'var(--surface2)', border: '1.5px solid var(--border)', borderRadius: 16, padding: '8px 8px 8px 16px', transition: 'border-color .2s' }}
            onFocus={() => {}}
          >
            <textarea
              ref={inputRef}
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Décrivez vos besoins... (ex: prof de maths pour le bac, en ligne, budget 40 DT/h)"
              rows={1}
              style={{
                flex: 1, background: 'none', border: 'none', outline: 'none',
                color: 'var(--text)', fontSize: '.9rem', lineHeight: 1.5,
                resize: 'none', maxHeight: 120, fontFamily: 'inherit',
                overflowY: 'auto', paddingTop: 6, paddingBottom: 6,
              }}
              onInput={e => {
                e.target.style.height = 'auto';
                e.target.style.height = Math.min(e.target.scrollHeight, 120) + 'px';
              }}
            />
            <button
              onClick={() => sendMessage()}
              disabled={!input.trim() || loading}
              style={{
                width: 42, height: 42, borderRadius: 12,
                background: !input.trim() || loading ? 'var(--border)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)',
                border: 'none', cursor: !input.trim() || loading ? 'not-allowed' : 'pointer',
                color: '#fff', fontSize: '1.1rem', display: 'flex', alignItems: 'center', justifyContent: 'center',
                transition: 'all .2s', flexShrink: 0,
                boxShadow: input.trim() && !loading ? '0 3px 10px rgba(108,99,255,0.35)' : 'none',
              }}
            >
              {loading ? '⏳' : '🚀'}
            </button>
          </div>
          <div style={{ fontSize: '.68rem', color: 'var(--text2)', marginTop: 6, textAlign: 'center' }}>
            Entrée pour envoyer · Shift+Entrée pour nouvelle ligne
          </div>
        </div>
      </div>

      {/* ════ COLONNE DROITE — Résultats matching ════ */}
      <div style={{ width: 380, display: 'flex', flexDirection: 'column', background: 'var(--surface)', flexShrink: 0 }}>

        {/* Header résultats */}
        <div style={{ padding: '20px 22px', borderBottom: '1px solid var(--border)' }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem', marginBottom: 4 }}>
            🏆 Professeurs recommandés
          </div>
          <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>
            {top3Profs.length > 0
              ? `${top3Profs.length} résultat${top3Profs.length > 1 ? 's' : ''} selon vos critères`
              : 'Les résultats apparaissent ici après votre recherche'}
          </div>
        </div>

        {/* Contenu */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '16px' }}>
          {top3Profs.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 20px', color: 'var(--text2)' }}>
              <div style={{ fontSize: '3rem', marginBottom: 16, opacity: .5 }}>🎯</div>
              <div style={{ fontWeight: 600, marginBottom: 8, color: 'var(--text)' }}>Aucune recommandation</div>
              <div style={{ fontSize: '.82rem', lineHeight: 1.6 }}>
                Décrivez vos besoins dans le chat pour recevoir des recommandations personnalisées avec un score de matching.
              </div>
              <div style={{ marginTop: 20, fontSize: '.78rem', color: 'var(--text2)', padding: '14px', background: 'var(--surface2)', borderRadius: 12, border: '1px solid var(--border)', textAlign: 'left' }}>
                <div style={{ fontWeight: 700, marginBottom: 8 }}>💡 Comment ça marche :</div>
                <div>1. Mentionnez la <strong>matière</strong> souhaitée</div>
                <div>2. Précisez votre <strong>niveau</strong></div>
                <div>3. Indiquez le <strong>mode</strong> (en ligne/présentiel)</div>
                <div>4. Donnez votre <strong>budget</strong> si besoin</div>
              </div>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              {top3Profs.map((prof, i) => (
                <ProfChatCard
                  key={prof.id}
                  prof={prof}
                  rank={i + 1}
                  onViewProfile={handleViewProfile}
                  onReserve={handleReserve}
                />
              ))}

              {/* Légende score */}
              <div style={{ padding: '14px', background: 'var(--surface2)', borderRadius: 14, border: '1px solid var(--border)', fontSize: '.72rem', color: 'var(--text2)' }}>
                <div style={{ fontWeight: 700, marginBottom: 8, color: 'var(--text)', fontSize: '.78rem' }}>📊 Barème de matching</div>
                {[
                  ['🟢', '80-100', 'Excellent match'],
                  ['🔵', '65-79',  'Très bon match'],
                  ['🟡', '50-64',  'Bon match'],
                  ['🔴', '< 50',   'Match possible'],
                ].map(([dot, range, label]) => (
                  <div key={range} style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 4 }}>
                    <span style={{ fontSize: 10 }}>{dot}</span>
                    <span style={{ fontWeight: 600, minWidth: 45 }}>{range}</span>
                    <span>{label}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Modal profil prof */}
      {selectedProf && (
        <ProfModal prof={selectedProf} onClose={() => setSelectedProf(null)} />
      )}
    </div>
  );
}
